import { products, money } from './catalog.js';
const $=s=>document.querySelector(s),view=$('#view'),dialog=$('#cartDialog');
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
let cart=read('nm-cart',[]); if(!Array.isArray(cart))cart=[];cart=cart.filter(id=>products.some(p=>p.id===id));cart=[...new Set(cart)];
let orders=read('nm-demo-orders',[]);if(!Array.isArray(orders))orders=[];orders=orders.filter(o=>o&&Array.isArray(o.items)&&typeof o.id==='string'&&Number.isFinite(o.date));
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const save=()=>{try{localStorage.setItem('nm-cart',JSON.stringify(cart));localStorage.setItem('nm-demo-orders',JSON.stringify(orders))}catch{}$('#cartCount').textContent=cart.length};
const find=id=>products.find(p=>p.id===id);const selected=()=>cart.map(find).filter(Boolean);const total=()=>selected().reduce((n,p)=>n+p.price,0);
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2500)}
function add(id){if(!find(id))return;if(cart.includes(id)){toast('Dieses Produkt liegt bereits im Warenkorb.');return}cart.push(id);save();toast('Zum Warenkorb hinzugefügt.');renderCart()}
const card=p=>`<article class="card"><a class="card-image" href="#product/${p.id}" aria-label="${p.name} ansehen"><img src="${p.image}" alt="${p.name} – Produktvorschau" loading="lazy"></a><div class="card-body"><h3><a href="#product/${p.id}">${p.name}</a></h3><p>${p.contents}</p><div class="card-bottom"><span class="price">${money(p.price)}</span><button class="icon-button" data-add="${p.id}" aria-label="${p.name} in den Warenkorb">＋</button></div></div></article>`;
const collection=(full=false)=>`<section class="panel collections"><div class="section-title"><div><h2>${full?'Alle Kollektionen':'Entdecke die Kollektionen'}</h2><p>Ausgewählte Designs für deinen digitalen Alltag.</p></div>${full?'<input class="search" id="search" type="search" aria-label="Produkte suchen" placeholder="Kollektion suchen …">':'<a href="#collections">Alle Produkte anzeigen →</a>'}</div>${full?'<div class="filters"><button class="chip active" data-filter="Alle">Alle</button><button class="chip" data-filter="Wallpaper">Wallpaper</button><button class="chip" data-filter="Streaming">Streaming</button></div>':''}<div class="grid" id="productGrid">${products.map(card).join('')}</div><p class="muted">Beispielprodukte und Beispielpreise · Die fertigen Pakete sind noch in Vorbereitung.</p><div class="benefits"><div>↓ &nbsp; Dein Downloadbereich<br><span>Alle Testkäufe an einem Ort</span></div><div>∞ &nbsp; Für deine Kreativität<br><span>Wallpaper, Panels und mehr</span></div><div>♡ &nbsp; Mit Liebe zum Detail<br><span>Der Look von NeonMind</span></div></div></section>`;
function home(){view.innerHTML=`<section class="hero"><div class="hero-copy"><span class="kicker">Digitale Designs · NeonMind</span><h1>Dein Bildschirm.<br><em>Deine Welt.</em></h1><p>Digitale Designs von NeonMind.</p><a class="button primary" href="#collections">Kollektion entdecken <span>→</span></a><div class="facts"><span><b>▧</b> Eigene<br>Designwelten</span><span><b>◇</b> Sorgfältige<br>Gestaltung</span><span><b>▯</b> Für PC &<br>Smartphone</span></div></div></section>${collection()}`}
function product(id){const p=find(id);if(!p){view.innerHTML='<div class="panel page empty"><h1>Produkt nicht gefunden</h1><a class="button" href="#collections">Zur Übersicht</a></div>';return}view.innerHTML=`<section class="page"><div class="breadcrumb"><a href="#home">Entdecken</a> › <a href="#collections">${p.category}</a> › ${p.name}</div><div class="panel product-layout"><div><img class="product-image" src="${p.image}" alt="${p.name} große Vorschau"><p class="muted">Motivvorschau · Noch kein vollständiges Produktpaket</p></div><div class="product-copy"><span class="kicker">${p.category} / NeonMind</span><h1>${p.name}</h1><p>${p.description}</p><span class="price">${money(p.price)}</span><span class="muted"> · Beispielpreis</span><ul class="detail-list"><li>${p.contents}</li><li>${p.formats}</li><li>Nutzungsrechte: werden vor Verkaufsstart festgelegt</li></ul><button class="button primary" data-add="${p.id}">＋ In den Warenkorb</button><p class="notice">Diese Vorschau nimmt keine Zahlungen an. Im Testkauf erhältst du ein einzelnes öffentliches Demobild.</p></div></div></section>`}
function renderCart(){const items=selected();$('#cartContent').innerHTML=items.length?`${items.map(p=>`<div class="cart-row"><img src="${p.image}" alt=""><div class="row-copy"><h3>${p.name}</h3><button class="remove" data-remove="${p.id}">Entfernen</button></div><span class="price">${money(p.price)}</span></div>`).join('')}<div class="summary-line total"><span>Gesamt</span><span>${money(total())}</span></div><p class="muted">Beispielpreise · Keine tatsächliche Zahlung</p><div class="cart-actions"><a class="button primary" href="#checkout" id="checkoutLink">Zur Testkasse →</a><button class="button" id="continueShopping">Weiter entdecken</button></div>`:'<div class="empty"><h2>Hier ist noch Platz.</h2><p class="muted">Entdecke deine nächste Designwelt.</p><button class="button primary" id="continueShopping">Kollektionen ansehen</button></div>'}
function checkout(){if(!cart.length){view.innerHTML='<div class="panel page empty"><h2>Dein Warenkorb ist leer.</h2><a class="button primary" href="#collections">Kollektionen entdecken</a></div>';return}view.innerHTML=`<section class="page"><div class="breadcrumb"><a href="#collections">Kollektionen</a> › Testkasse</div><h1 style="font-size:40px">Deine Auswahl.</h1><p class="muted">Ein Testdurchlauf ohne Zahlung und ohne persönliche Daten.</p><div class="checkout-grid"><form class="panel" id="checkoutForm"><h2>Testkauf</h2><p>Der echte Zahlungsanschluss wird nach Einrichtung deines Betreiberkontos ergänzt.</p><label class="field">Testablauf<select id="testResult"><option value="success">Erfolgreicher Testkauf</option><option value="pending">Zahlung ausstehend simulieren</option><option value="failed">Fehlgeschlagene Zahlung simulieren</option></select></label><label class="check"><input type="checkbox" required>Ich verstehe, dass dies eine Vorschau mit Beispielprodukten ist und kein echter Kauf stattfindet.</label><button class="button primary" type="submit">Testkauf durchführen</button><p class="notice">Die Testhistorie wird nur in diesem Browser gespeichert. Sie bestätigt keine echte Zahlung und schaltet keine privaten Produkte frei.</p></form><aside class="panel"><h2>Bestellübersicht</h2>${selected().map(p=>`<div class="summary-line"><span>${p.name}</span><strong>${money(p.price)}</strong></div>`).join('')}<div class="summary-line total"><span>Beispielgesamtpreis</span><span>${money(total())}</span></div><p class="muted">Heute zahlst du: 0,00 €</p></aside></div></section>`;$('#checkoutForm').addEventListener('submit',e=>{e.preventDefault();const status=$('#testResult').value;if(status!=='success'){view.innerHTML=`<div class="panel page success"><h2>${status==='pending'?'Testzahlung ausstehend':'Testzahlung fehlgeschlagen'}</h2><p>Es wurden keine Downloads freigegeben.</p><button class="button primary" id="retryCheckout">Zurück zur Testkasse</button></div>`;return}const order={id:crypto.randomUUID(),date:Date.now(),items:[...cart],mode:'demo'};orders.unshift(order);cart=[];save();location.hash='#success/'+order.id})}
function downloads(){const bought=[...new Set(orders.flatMap(o=>o.items))].map(find).filter(Boolean);view.innerHTML=`<section class="page"><div class="panel"><span class="kicker">Deine Designbibliothek</span><h1 style="font-size:42px">Meine Downloads</h1><p class="muted">Hier findest du die Demodateien deiner Testkäufe.</p>${bought.length?bought.map(p=>`<article class="download-row"><img src="${p.image}" alt=""><div class="row-copy"><h3>${p.name}</h3><p>Ein Demobild · Öffentliches Vorschauasset</p><span class="status">✓ Testkauf abgeschlossen</span></div><a class="button" href="${p.demo}" download="NeonMind-${p.id}-Demo.png">↓ Demobild herunterladen</a></article>`).join(''):'<div class="empty"><h2>Deine Sammlung beginnt hier.</h2><p class="muted">Nach einem Testkauf erscheint dein Demobild in diesem Bereich.</p><a class="button primary" href="#collections">Designs entdecken</a></div>'}<p class="notice">Im fertigen Shop werden private Downloads serverseitig freigegeben. Diese Vorschau verwendet ausschließlich öffentliche Demobilder.</p>${orders.length?'<button class="button" id="resetDemo">Testhistorie löschen</button>':''}</div></section>`}
function route(){dialog.close();const [page,id]=(location.hash.slice(1)||'home').split('/');if(page==='product')product(id);else if(page==='collections'){view.innerHTML='<div class="page">'+collection(true)+'</div>';let filter='Alle';const update=()=>{const q=$('#search').value.toLowerCase();const result=products.filter(p=>(filter==='Alle'||p.category===filter)&&p.name.toLowerCase().includes(q));$('#productGrid').innerHTML=result.length?result.map(card).join(''):'<p class="muted">Keine passende Kollektion gefunden.</p>'};$('#search').addEventListener('input',update);document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));update()}))}else if(page==='checkout')checkout();else if(page==='downloads')downloads();else if(page==='success'){const order=orders.find(o=>o.id===id);view.innerHTML=order?'<section class="page panel success"><span class="success-symbol">✓</span><h1 style="font-size:40px">Deine Designs warten.</h1><p>Der Testkauf ist abgeschlossen. Es wurde kein Geld abgebucht.</p><a class="button primary" href="#downloads">Zu meinen Downloads →</a></section>':'<div class="panel page empty"><h2>Testbestellung nicht gefunden.</h2><a href="#downloads">Zu den Downloads</a></div>'}else if(page==='info')view.innerHTML='<section class="page"><div class="panel content"><h1 style="font-size:40px">Über diese Vorschau</h1><p>NeonMind Shop ist ein eigenständiges Projekt von NeonMind. Diese private Vorschau zeigt das bestätigte Design und den geplanten Kaufablauf.</p><h2>Kein aktiver Verkauf</h2><p>Alle Preise und Produktpakete sind Beispiele. Es werden keine Zahlungen angenommen und keine persönlichen Kundendaten abgefragt. Testkäufe und Warenkorb werden lokal in deinem Browser gespeichert.</p><h2>Vor dem Verkaufsstart</h2><p>Betreiberangaben, Kontaktadresse, Impressum, Datenschutz, Verkaufsbedingungen und Nutzungsrechte werden mit den tatsächlichen Angaben ergänzt. Der Zahlungsanbieter und der private Dateispeicher sind noch einzurichten.</p><a class="button" href="#home">Zurück zum Shop</a></div></section>';else home();document.title=(page==='product'&&find(id)?find(id).name+' · ':'')+'NeonMind Shop';window.scrollTo(0,0)}
document.addEventListener('click',e=>{const addButton=e.target.closest('[data-add]');if(addButton)add(addButton.dataset.add);const remove=e.target.closest('[data-remove]');if(remove){cart=cart.filter(id=>id!==remove.dataset.remove);save();renderCart()}if(e.target.closest('#continueShopping')){dialog.close();location.hash='#collections'}if(e.target.closest('#checkoutLink'))dialog.close();if(e.target.closest('#retryCheckout'))checkout();if(e.target.closest('#resetDemo')){orders=[];save();downloads();toast('Testhistorie gelöscht.')}});
$('#cartButton').addEventListener('click',()=>{renderCart();dialog.showModal()});$('#closeCart').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});window.addEventListener('hashchange',route);save();route();
